using System;using System.Linq;using System.Collections.Generic;using System.Globalization;
namespace BeamScheduleFormatter {
static partial class WindAssessment {
 static string F(double value){return WindTin.Finite(value)?value.ToString("0.######",CultureInfo.InvariantCulture):"Unresolved";}
 static void Unity(WindDirection value,string reason){value.K1=0;value.K2=value.K3=1;value.Kzt=1;value.TopographicReason=reason;value.TopographicChecks.Add(new[]{"Topographic amplification","Not triggered",reason});value.TopographicChecks.Add(new[]{"Applied substitution","Kzt = (1 + 0 × 1 × 1)² = 1.00","K1 is set to zero because the feature model is not triggered; the unused multipliers are shown as unity."});}
 public static List<WindDirection> Calculate(WindTerrain terrain,double height,double velocity,double kd,double? exposureHeight=null){if(terrain==null||!WindTin.Finite(height)||height<=0||height>150||!WindTin.Finite(velocity)||velocity<=0||!WindTin.Finite(kd)||kd<=0||kd>1)throw new Exception("Check reference height (0–150m), wind speed and Kd.");var results=new List<WindDirection>();for(int direction=0;direction<8;direction++){
 var up=terrain.Rays[direction*3+1];var down=terrain.Rays[((direction+4)%8)*3+1];var profile=down.Skip(1).Reverse().Select(p=>new WindSample{Lat=p.Lat,Lon=p.Lon,D=-p.D,Z=p.Z,Cover=p.Cover}).Concat(up).ToList();var exposure=AssessExposure(terrain,direction,exposureHeight??height);var result=new WindDirection{Name=Directions[direction],Exposure=exposure.Exposure,ExposureAudit=exposure,Shape="Unresolved",Profile=profile};results.Add(result);result.TopographicChecks.Add(new[]{"Height used for Kzt",F(height)+" m above local ground","This is z; exposure fetch separately uses mean roof height h."});
 if(result.Exposure=="Unresolved"||profile.Count<5||profile.Any(p=>!WindTin.Finite(p.Z))){result.Status=result.TopographicReason="Insufficient exposure/elevation data. Kzt is unresolved, not assumed to be1.00.";result.TopographicChecks.Add(new[]{"Data sufficiency","UNRESOLVED",result.TopographicReason});continue;}
 result.Kz=Kz(height,result.Exposure);double threshold=result.Exposure=="B"?18.288:4.572,range=profile.Max(p=>p.Z)-profile.Min(p=>p.Z);result.TopographicChecks.Add(new[]{"Minimum feature height",F(threshold)+" m",result.Exposure=="B"?"Exposure B: 60ft equivalent":"Exposure C/D: 15ft equivalent"});
 if(range<threshold){result.H=range;result.Shape="Low relief";Unity(result,"Sampled relief H = "+F(range)+" m is below "+F(threshold)+" m for Exposure "+result.Exposure+". Local topographic amplification is not triggered.");}
 else{
  var crest=profile.OrderByDescending(p=>p.Z).First();var windward=profile.Where(p=>p.D>crest.D).ToList();var leeward=profile.Where(p=>p.D<crest.D).ToList();if(windward.Count==0||leeward.Count==0){result.Status=result.TopographicReason="Crest lies at the profile boundary. Extend investigation; Kzt remains unresolved.";continue;}
  double baseline=windward.Min(p=>p.Z),lee=leeward.Min(p=>p.Z),site=up[0].Z;result.H=crest.Z-baseline;result.X=-crest.D;result.Shape=crest.Z-lee<.3*result.H?"Escarpment":"Hill";var cross=terrain.Cross[direction];if(result.Shape!="Escarpment"&&cross.Count>0&&cross.All(p=>WindTin.Finite(p.Z))&&cross.Max(p=>p.Z)-cross.Min(p=>p.Z)<.3*result.H)result.Shape="Ridge";
  result.TopographicChecks.Add(new[]{"Feature candidate",result.Shape,"DEM longitudinal/cross-profile shape; verify isolation and actual terrain."});result.TopographicChecks.Add(new[]{"Crest / upwind baseline",F(crest.Z)+" / "+F(baseline)+" m","H uses the upwind reference terrain, not a lower leeward valley."});result.TopographicChecks.Add(new[]{"Feature height H",F(result.H)+" m","H = crest elevation − upwind baseline"});result.TopographicChecks.Add(new[]{"Signed site-to-crest x",F(result.X)+" m","Positive windward, negative leeward."});
  var flank=profile.Where(p=>p.D>=crest.D).OrderBy(p=>p.D).ToList();double half=crest.Z-result.H/2;for(int n=1;n<flank.Count;n++)if(flank[n].Z<=half){var a=flank[n-1];var b=flank[n];double t=Math.Abs(b.Z-a.Z)<1e-9?0:(half-a.Z)/(b.Z-a.Z);result.Lh=a.D+t*(b.D-a.D)-crest.D;break;}
  result.TopographicChecks.Add(new[]{"Windward half-height elevation",F(half)+" m","Crest − H/2; interpolate its first windward crossing."});result.TopographicChecks.Add(new[]{"Lh",F(result.Lh)+" m","Horizontal crest-to-windward-half-height distance."});
  if(result.H<threshold)Unity(result,"H = "+F(result.H)+" m is below the "+F(threshold)+" m height trigger, even though the DEM shape is "+result.Shape+".");
  else if(!WindTin.Finite(result.Lh)||result.Lh<=0){result.Status=result.TopographicReason="No valid windward half-height crossing. Lh and Kzt remain unresolved.";continue;}
  else{
   double slope=result.H/result.Lh,upper=baseline+result.H/2;bool steep=slope>=.2,upperHalf=site>=upper;result.TopographicChecks.Add(new[]{"Slope H/Lh",F(slope),steep?"PASS: >=0.20":"NOT TRIGGERED: <0.20"});result.TopographicChecks.Add(new[]{"Upper-half site criterion",F(site)+" m site; "+F(upper)+" m threshold",upperHalf?"PASS: site is in the sampled upper half":"NOT TRIGGERED: site is below the sampled upper half"});
   if(!steep||!upperHalf)Unity(result,(!steep?"H/Lh = "+F(slope)+" <0.20. ":"")+(!upperHalf?"Site elevation "+F(site)+" m < upper-half threshold "+F(upper)+" m. ":"")+"A hill shape alone does not activate Kzt amplification.");
   else{var factors=Factors(result.H,result.Lh,result.X,height,result.Exposure,result.Shape);result.K1=factors[0];result.K2=factors[1];result.K3=factors[2];result.Kzt=factors[3];double effective=Math.Max(result.Lh,2*result.H);result.TopographicChecks.Add(new[]{"Effective Lh",F(effective)+" m","max(Lh,2H); H/Lh capped at0.5 for K1"});result.TopographicChecks.Add(new[]{"K1 / K2 / K3",F(result.K1)+" / "+F(result.K2)+" / "+F(result.K3),"K1=A min(H/Lh,0.5); K2=max(0,1−|x|/(μLe)); K3=exp(−γz/Le)"});result.TopographicChecks.Add(new[]{"Numerical substitution","Kzt = (1 + "+F(result.K1)+" × "+F(result.K2)+" × "+F(result.K3)+")² = "+F(result.Kzt),"Evaluate with full precision; displayed values are rounded."});result.TopographicReason=result.K2==0?"Site lies outside the feature's horizontal amplification zone: K2=0, so Kzt=1.00.":"Sampled height, slope and upper-half tests activate the feature calculation. Isolation, feature extent and neighbouring terrain still require review.";}
  }
 }
 result.Qz=.613*result.Kz*result.Kzt*kd*Math.Pow(velocity/3.6,2)/1000;result.Status=result.TopographicReason+" DEM/land-cover screening candidate; verify site evidence.";result.TopographicChecks.Add(new[]{"Engineering review","Required","Confirm feature isolation/protrusion, upwind terrain, source resolution and actual site conditions."});
 }return results;}
}
}
